#include "256.h"#include "FileStuff.h"#include "BMP.h"OSErr getColors ();OSErr getColors (){//----------------------------------vars--------------------------------------------------	short		thePlugFileRef;	long		theWidth, theHeight, theSize;	OSErr		theError;	int			i, j, k, x, y;	char *theTexture;	StandardFileReply	theReply;	SFTypeList			theTypeList = { 0, 0, 0, 0 };	Point myPoint;	_256Header thePlugHeader;	Myth256Palette thePalette;//----------------------------------------------------------------------------------------	// plug	SetPt ( &myPoint, -1, -1);	CustomGetFile ( nil, 0, theTypeList, &theReply, 4001, myPoint,  nil, nil, nil, nil, nil );	if ( theReply.sfGood != true )		return -1;			theError = FSpOpenDF ( &theReply.sfFile, fsCurPerm, &thePlugFileRef );	if ( theError != noErr )		return theError;	FileRead ( &thePlugHeader, sizeof( _256Header ), thePlugFileRef );	if ( thePlugHeader.type != '.256' ){		ParamText( "\pNot a valid .256 file.", "\p", "\p", "\p" );		StopAlert ( 400, nil );		FSClose ( thePlugFileRef );		return -1;	}	theWidth = 256;	theHeight = 256;	theSize = theWidth * theHeight;	FileSeek ( thePlugFileRef, 384L );	FileRead ( &thePalette, 2080L, thePlugFileRef );			theTexture = (char *) NewPtr ( theSize );	if ( theTexture == nil ){		FSClose ( thePlugFileRef );		return -1;	}	// get the grid Z data into an array	for ( y = 0, i = 0; y < theSize - theWidth * 15; y += theWidth * 16 ){		for ( x = 0; x < theWidth - 15; x += 16, i++ ){			for ( k = 0; k < 16; k++ )				for ( j = 0; j < 16; j++ )					theTexture[x + y + j + k * theWidth] = i;		}	}	theError = writeBMP( "\p:Graphics.out:colors.bmp", theWidth, theHeight, &thePalette, theTexture );	DisposePtr ( theTexture );	FSClose ( thePlugFileRef );	return theError;}